mod encode {
    use variable_length_quantity::encode;

    #[test]
    fn zero() {
        let integers = array![0];
        let expected = array![0];

        let result = encode(integers);

        assert_eq!(result, expected);
    }

    #[test]
    #[ignore]
    fn arbitrary_single_byte() {
        let integers = array![64];
        let expected = array![64];

        let result = encode(integers);

        assert_eq!(result, expected);
    }

